/* Expense Calculator: app logic (balances, transactions, EMIs, budget, reports) */
{
let U={email:'',name:'',demo:false};
const T=new Date();
const pad=n=>String(n).padStart(2,'0');
const iso=d=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
const TODAY=iso(T);
const addD=(s,k)=>{const d=new Date(s+'T12:00');d.setDate(d.getDate()+k);return iso(d)};
const M=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const ML=['January','February','March','April','May','June','July','August','September','October','November','December'];
const WD=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const fmt=n=>'Rs '+Math.round(Math.abs(n)).toLocaleString('en-IN');
const sfmt=n=>(n<0?'−':'')+fmt(n);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let seq=Date.now();const nid=()=>'i'+(seq++).toString(36);
const dshort=s=>{const d=new Date(s+'T12:00');return `${d.getDate()} ${M[d.getMonth()]}`};
const dlong=s=>{if(s===TODAY)return'Today';if(s===addD(TODAY,-1))return'Yesterday';const d=new Date(s+'T12:00');return `${WD[d.getDay()]}, ${d.getDate()} ${M[d.getMonth()]}`};

const I={cam:'M4 8h3l2-3h6l2 3h3v11H4zM12 10a3.5 3.5 0 1 0 0 7 3.5 3.5 0 0 0 0-7z',home:'M3 11 12 4l9 7M5 10v10h14V10',list:'M8 6h13M8 12h13M8 18h13M3.5 6h.01M3.5 12h.01M3.5 18h.01',cal:'M4 5h16v16H4zM4 10h16M8 3v4M16 3v4',pie:'M12 3v9h9a9 9 0 1 1-9-9zM15 3.3A9 9 0 0 1 20.7 9H15z',wallet:'M3 7h16a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2zM3 7l12-4v4M16 13.5h2',plus:'M12 5v14M5 12h14',gear:'M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6zM12 2v3M12 19v3M4.9 4.9l2.1 2.1M17 17l2.1 2.1M2 12h3M19 12h3M4.9 19.1 7 17M17 7l2.1-2.1',search:'M11 4a7 7 0 1 0 0 14 7 7 0 0 0 0-14zM20 20l-4-4',clip:'M20 11.5 12 19.5a5 5 0 0 1-7-7L13.5 4a3.5 3.5 0 0 1 5 5L10 17.5a2 2 0 0 1-3-3L15 6.5',x:'M6 6l12 12M18 6 6 18',cl:'M15 6l-6 6 6 6',cr:'M9 6l6 6-6 6',swap:'M7 4 3 8l4 4M3 8h14M17 20l4-4-4-4M21 16H7',check:'M5 12l5 5 9-10',user:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8zM4 21a8 8 0 0 1 16 0',cash:'M2 6h20v12H2zM12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6zM5.5 9v6M18.5 9v6',card:'M2 5h20v14H2zM2 10h20M6 15h4',phone:'M7 2h10v20H7zM11 18h2',bank:'M3 21h18M5 21V10M19 21V10M9.5 21V10M14.5 21V10M2 10l10-6 10 6z',food:'M4 3v8a2 2 0 0 0 2 2 2 2 0 0 0 2-2V3M6 13v8M18 3c-2 0-3 2-3 5.5S16 13 18 13v8',car:'M3 13l2-6h14l2 6v5H3zM6.5 18v2M17.5 18v2M3 13h18M7 15.5h.01M17 15.5h.01',bolt:'M13 2 4 14h7l-1 8 9-12h-7z',bag:'M5 8h14l-1 13H6zM9 8V6a3 3 0 0 1 6 0v2',heart:'M12 20s-7-4.5-7-10a4 4 0 0 1 7-2.6A4 4 0 0 1 19 10c0 5.5-7 10-7 10z',book:'M4 5a2 2 0 0 1 2-2h14v15H6a2 2 0 0 0-2 2zM4 20V5M8 21h12',play:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18zM10 8.5v7l6-3.5z',gift:'M4 11h16v10H4zM3 7h18v4H3zM12 7v14M12 7C11 4 7 3 7 5.5 7 7 9 7 12 7zM12 7c1-3 5-4 5-1.5C17 7 15 7 12 7z',pct:'M19 5 5 19M7 5a2 2 0 1 0 0 4 2 2 0 0 0 0-4zM17 15a2 2 0 1 0 0 4 2 2 0 0 0 0-4z',dots:'M5 12h.01M12 12h.01M19 12h.01',brief:'M3 8h18v12H3zM8 8V5h8v3M3 13h18',store:'M4 10v10h16V10M3 4h18l-1 6H4zM9.5 20v-6h5v6',undo:'M3 12a9 9 0 1 0 3-6.7M3 4v5h5',hand:'M7 11V6a1.5 1.5 0 0 1 3 0v4M10 10V4.5a1.5 1.5 0 0 1 3 0V10M13 10V5.5a1.5 1.5 0 0 1 3 0V12M16 9.5a1.5 1.5 0 0 1 3 0V14a7 7 0 0 1-7 7h-1a6 6 0 0 1-5-3l-2.5-4.5a1.5 1.5 0 0 1 2.5-1.5L7 13',trash:'M4 7h16M10 11v6M14 11v6M6 7l1 14h10l1-14M9 7V4h6v3',del:'M21 5H9l-6 7 6 7h12zM12 9l6 6M18 9l-6 6',adj:'M4 21v-7M4 10V3M12 21v-9M12 8V3M20 21v-5M20 12V3M2 14h4M10 8h4M18 16h4',copy:'M8 8h12v12H8zM4 16V4h12'};
const ic=(n,s=20,w=1.8)=>`<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="${n==='dots'?3:w}" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${I[n]}"/></svg>`;

const CATS=[['food','Food','Food & groceries'],['rent','Rent','Rent & housing','home'],['trans','Transport','Transport & fuel','car'],['bills','Bills','Bills & utilities','bolt'],['emi','EMI','EMI & loans','bank'],['shop','Shopping','Shopping','bag'],['health','Health','Health','heart'],['edu','Education','Education','book'],['fun','Fun','Entertainment','play'],['gift','Gifts','Gifts & donations','gift'],['fees','Fees','Bank & fees','pct'],['other','Other','Other','dots']].map((c,k)=>({id:c[0],s:c[1],n:c[2],i:c[3]||c[0],c:['#ea580c','#7c3aed','#0284c7','#a16207','#1e40af','#db2777','#0d9488','#4f46e5','#c026d3','#e11d48','#57534e','#64748b'][k]}));
const SRCS=[['salary','Salary','Salary','brief'],['rentin','Rent','Rent received','home'],['biz','Business','Business','store'],['giftin','Gift','Gift / from someone','gift'],['refund','Refund','Refund','undo'],['interest','Interest','Interest','pct'],['oth','Other','Other income','dots']].map(c=>({id:c[0],s:c[1],n:c[2],i:c[3],c:'#047857'}));
const ATYPE={bank:['Bank','bank'],wallet:['Wallet','phone'],cash:['Cash','cash'],card:['Credit card','card']};
const CTYPE=['EMI','Rent','Bill','Subscription','Insurance','Other'];

let S;
function period(off=0){const s=S.set.start;let y=T.getFullYear(),m=T.getMonth();if(T.getDate()<s)m--;m+=off;const a=new Date(y,m,s,12),b=new Date(y,m+1,s,12);const e=new Date(b);e.setDate(e.getDate()-1);const label=s===1?`${ML[a.getMonth()]} ${a.getFullYear()}`:`${a.getDate()} ${M[a.getMonth()]} – ${e.getDate()} ${M[e.getMonth()]}`;return{a:iso(a),b:iso(b),label,ad:a,short:s===1?M[a.getMonth()]:`${a.getDate()} ${M[a.getMonth()]}`}}
const inP=(t,p)=>t.date>=p.a&&t.date<p.b;

function slip(amt,title,lines,kind){const L=lines.map((l,i)=>`<text x='24' y='${232+i*30}' font-family='Arial' font-size='13' fill='#777'>${l[0]}</text><text x='276' y='${232+i*30}' font-family='Arial' font-size='13' text-anchor='end' fill='#111'>${l[1]}</text>`).join('');const head=kind==='bill'?`<text x='24' y='52' font-family='Arial' font-size='18' font-weight='700' fill='#111'>${title}</text><text x='24' y='74' font-family='Arial' font-size='12' fill='#777'>Tax invoice</text><text x='24' y='150' font-family='Arial' font-size='12' fill='#777'>Total</text><text x='24' y='182' font-family='Arial' font-size='30' font-weight='700' fill='#111'>Rs ${amt}</text>`:`<circle cx='150' cy='66' r='26' fill='#111'/><path d='M138 66l8 8 16-17' stroke='#fff' stroke-width='4' fill='none' stroke-linecap='round'/><text x='150' y='128' font-family='Arial' font-size='14' text-anchor='middle' fill='#555'>${title}</text><text x='150' y='170' font-family='Arial' font-size='30' font-weight='700' text-anchor='middle' fill='#111'>Rs ${amt}</text>`;const svg=`<svg xmlns='http://www.w3.org/2000/svg' width='600' height='840' viewBox='0 0 300 420'><rect width='300' height='420' fill='#fff'/>${head}<line x1='24' x2='276' y1='204' y2='204' stroke='#bbb' stroke-dasharray='4 4'/>${L}</svg>`;return'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg)}

function seed(){
  S={set:{start:1,def:'esewa',theme:(S&&S.set&&S.set.theme)||'light'},acc:[],tx:[],com:[],bud:{all:60000,cat:{food:10000,shop:6000,trans:4000,fun:2000}}};
  const P0=period(0),P1=period(-1);const el=Math.max(0,Math.round((new Date(TODAY+'T12:00')-P0.ad)/864e5));
  S.acc=[['cash','Cash','cash',3500],['prabhu','Prabhu Bank','bank',62000],['sc','SC Bank','bank',20000],['esewa','eSewa','wallet',9000],['khalti','Khalti','wallet',6000],['card','SC Credit Card','card',0]].map(a=>({id:a[0],name:a[1],type:a[2],open:a[3]}));
  const sl=(a,t,l)=>[{id:nid(),label:'Payment slip',url:slip(a,t,l),name:'slip.svg'}];
  const bl=(a,t,l)=>[{id:nid(),label:'Bill',url:slip(a,t,l,'bill'),name:'bill.svg'}];
  const R=(base,cap)=>(k,type,amt,acc,x={})=>S.tx.push(Object.assign({id:nid(),type,amt,acc,date:addD(base,Math.min(k,cap)),note:'',att:[]},x));
  const a=R(P1.a,40),b=R(P0.a,el);
  a(0,'inc',85000,'sc',{cat:'salary',note:'Salary'});a(0,'exp',18000,'sc',{cat:'rent',note:'Flat rent',cid:'c_rent'});a(3,'inc',12000,'prabhu',{cat:'rentin',note:'Ground floor rent'});a(4,'exp',9800,'prabhu',{cat:'emi',note:'Bike loan',cid:'c_bike'});a(6,'exp',3100,'prabhu',{cat:'food',note:'Weekly groceries'});a(8,'exp',5400,'card',{cat:'shop',note:'Shoes'});a(10,'exp',1200,'esewa',{cat:'fun',note:'Movie night'});a(12,'tr',5400,'sc',{to:'card',note:'Card bill'});a(12,'exp',2400,'prabhu',{cat:'food',note:'Weekly groceries'});a(14,'exp',2600,'cash',{cat:'trans',note:'Petrol'});a(15,'exp',3200,'khalti',{cat:'emi',note:'Phone EMI',cid:'c_phone'});a(17,'exp',1500,'esewa',{cat:'bills',note:'Internet',cid:'c_net'});a(19,'exp',1340,'prabhu',{cat:'bills',note:'Electricity',cid:'c_elec'});a(20,'borrow',3000,'khalti',{person:'Bikash',note:'Short loan'});a(22,'exp',900,'cash',{cat:'health',note:'Clinic visit'});a(25,'exp',2800,'prabhu',{cat:'food',note:'Weekly groceries'});a(27,'exp',799,'card',{cat:'fun',note:'Streaming plan',cid:'c_stream'});a(28,'exp',2000,'cash',{cat:'gift',note:'Family visit'});
  b(0,'inc',85000,'sc',{cat:'salary',note:'Salary'});b(0,'exp',18000,'sc',{cat:'rent',note:'Flat rent',cid:'c_rent',att:sl('18,000','Transfer successful',[['To','House owner'],['From','SC Bank'],['Ref','FT2611-0042']])});b(2,'inc',12000,'prabhu',{cat:'rentin',note:'Ground floor rent'});b(4,'exp',9800,'prabhu',{cat:'emi',note:'Bike loan',cid:'c_bike',att:sl('9,800','EMI paid',[['Loan','Bike loan'],['Instalment','15 of 36'],['Ref','EMI-88213']])});b(5,'tr',5000,'prabhu',{to:'esewa',note:'Load wallet'});b(5,'exp',2860,'prabhu',{cat:'food',note:'Weekly groceries',att:bl('2,860','City Mart',[['Rice 5 kg','1,150'],['Vegetables','640'],['Milk, eggs','520'],['Other','550']])});b(6,'exp',300,'khalti',{cat:'trans',note:'Bike taxi'});b(7,'exp',1800,'sc',{cat:'health',note:'Pharmacy'});b(8,'lend',5000,'esewa',{person:'Suman',note:'For bike repair'});b(9,'tr',4000,'sc',{to:'cash',note:'ATM withdrawal'});b(10,'exp',3250,'card',{cat:'shop',note:'Winter jacket'});b(11,'exp',1450,'prabhu',{cat:'gift',note:'Wedding gift'});b(12,'inc',5000,'cash',{cat:'giftin',person:'Didi',note:'Tihar gift'});b(13,'exp',2400,'esewa',{cat:'edu',note:'Online course'});b(14,'exp',650,'cash',{cat:'food',note:'Tea and snacks'});b(15,'exp',500,'khalti',{cat:'bills',note:'Mobile recharge'});b(16,'exp',1200,'cash',{cat:'trans',note:'Petrol'});b(16,'exp',450,'esewa',{cat:'food',note:'Momo, Newroad',att:sl('450','Payment successful',[['To','Momo House'],['From','eSewa'],['Ref','ES-7719204']])});
  S.com=[{id:'c_rent',name:'Flat rent',type:'Rent',amt:18000,cat:'rent',acc:'sc',due:1},{id:'c_bike',name:'Bike loan',type:'EMI',amt:9800,cat:'emi',acc:'prabhu',due:5,lender:'Prabhu Bank',total:36,done:15},{id:'c_phone',name:'Phone EMI',type:'EMI',amt:3200,cat:'emi',acc:'khalti',due:15,lender:'Mobile store',total:12,done:7},{id:'c_net',name:'Internet',type:'Bill',amt:1500,cat:'bills',acc:'esewa',due:20},{id:'c_elec',name:'Electricity',type:'Bill',amt:1300,cat:'bills',acc:'prabhu',due:22,variable:true},{id:'c_stream',name:'Streaming plan',type:'Subscription',amt:799,cat:'fun',acc:'card',due:28}].map(c=>Object.assign({paid:[],skip:[],remind:2},c));
  for(const c of S.com){c.paid.push(dueIn(c,P1));if(['c_rent','c_bike'].includes(c.id))c.paid.push(dueIn(c,P0))}
}
function applyTheme(){const t=(S.set&&S.set.theme)||'light';const r=document.documentElement;if(t==='system')delete r.dataset.app;else r.dataset.app=t;const m=document.querySelector('meta[name=theme-color]');if(m)m.content=getComputedStyle(document.body).backgroundColor;try{localStorage.setItem('xt-theme',t)}catch(e){}}
function save(){Store.save(S)}
function blank(){S={set:{start:1,def:'cash',theme:(S&&S.set&&S.set.theme)||'light'},acc:[{id:'cash',name:'Cash',type:'cash',open:0}],tx:[],com:[],bud:{all:30000,cat:{}}}}
function fresh(){if(U.demo&&Store.mode==='local')seed();else blank()}

const accOf=id=>S.acc.find(a=>a.id===id)||{name:'Account',type:'bank'};
const catOf=id=>CATS.find(c=>c.id===id)||SRCS.find(c=>c.id===id)||{n:'Other',s:'Other',i:'dots',c:'#64748b'};
const cic=(id,sz=20)=>`<span class="ico cico" style="--c:${catOf(id).c}">${ic(catOf(id).i,sz)}</span>`;
function delta(t,a){const x=t.amt;switch(t.type){case'exp':case'lend':case'repayOut':return t.acc===a?-x:0;case'inc':case'borrow':case'repayIn':case'adj':return t.acc===a?x:0;case'tr':return(t.acc===a?-x:0)+(t.to===a?x:0)}return 0}
const bal=a=>a.open+S.tx.reduce((s,t)=>s+delta(t,a.id),0);
function people(){const m={};for(const t of S.tx){if(!t.person||!['lend','borrow','repayIn','repayOut'].includes(t.type))continue;const v={lend:1,repayIn:-1,borrow:-1,repayOut:1}[t.type]*t.amt;m[t.person]=(m[t.person]||0)+v}return m}
function stats(p){const r={exp:0,inc:0,cat:{},acc:{},src:{},day:{}};for(const t of S.tx){if(!inP(t,p))continue;if(t.type==='exp'){r.exp+=t.amt;r.cat[t.cat]=(r.cat[t.cat]||0)+t.amt;r.acc[t.acc]=(r.acc[t.acc]||0)+t.amt;r.day[t.date]=(r.day[t.date]||0)+t.amt}else if(t.type==='inc'){r.inc+=t.amt;r.src[t.cat]=(r.src[t.cat]||0)+t.amt}}return r}
function dueIn(c,p){let d=new Date(p.ad.getFullYear(),p.ad.getMonth(),c.due,12);if(iso(d)<p.a)d=new Date(p.ad.getFullYear(),p.ad.getMonth()+1,c.due,12);return iso(d)}
function cstat(c,p){const d=dueIn(c,p);if(c.type==='EMI'&&c.done>=c.total&&!c.paid.includes(d))return'done';if(c.paid.includes(d))return'paid';if(c.skip.includes(d))return'skipped';if(d<TODAY)return'overdue';if(d===TODAY)return'today';return'upcoming'}
const ORDER={overdue:0,today:1,upcoming:2,paid:3,skipped:4,done:5};
const PILL={overdue:'<span class="pill w">Overdue</span>',today:'<span class="pill dk">Due today</span>',upcoming:'<span class="pill">Upcoming</span>',paid:'<span class="pill">Paid</span>',skipped:'<span class="pill">Skipped</span>',done:'<span class="pill">Completed</span>'};
function money(){const live=S.acc.filter(a=>!a.archived);const liquid=live.filter(a=>a.type!=='card').reduce((s,a)=>s+bal(a),0);const owedCard=live.filter(a=>a.type==='card').reduce((s,a)=>s+Math.min(0,bal(a)),0);const p=period(0);const left=S.com.filter(c=>['overdue','today','upcoming'].includes(cstat(c,p))).reduce((s,c)=>s+c.amt,0);const paid=S.com.filter(c=>cstat(c,p)==='paid').reduce((s,c)=>s+(S.tx.find(t=>t.cid===c.id&&t.date>=p.a&&t.date<p.b)||c).amt,0);const pp=people();let owedMe=0,iOwe=0;for(const k in pp){if(pp[k]>0)owedMe+=pp[k];else iOwe-=pp[k]}const avail=liquid+owedCard;return{liquid,owedCard,avail,left,paid,free:avail-left,owedMe,iOwe,net:avail+owedMe-iOwe}}

function txView(t){const c=catOf(t.cat),a=accOf(t.acc);let title=t.note,sub,icon=c.i,sign=-1,dk=false;switch(t.type){case'exp':title=title||c.n;sub=`${c.s} · ${a.name}`;break;case'inc':title=title||c.n;sub=`${c.s}${t.person?' from '+t.person:''} · ${a.name}`;sign=1;break;case'tr':title=title||'Transfer';sub=`${a.name} → ${accOf(t.to).name}`;icon='swap';sign=0;break;case'lend':title=`Lent to ${t.person}`;sub=`${t.note?t.note+' · ':''}${a.name}`;icon='hand';dk=true;break;case'borrow':title=`Borrowed from ${t.person}`;sub=`${t.note?t.note+' · ':''}${a.name}`;icon='hand';sign=1;dk=true;break;case'repayIn':title=`${t.person} repaid`;sub=a.name;icon='hand';sign=1;dk=true;break;case'repayOut':title=`Repaid ${t.person}`;sub=a.name;icon='hand';dk=true;break;case'adj':title='Balance correction';sub=a.name;icon='adj';sign=t.amt<0?-1:1;break}const col=t.type==='exp'?c.c:t.type==='inc'?'#047857':t.type==='tr'||t.type==='adj'?'#64748b':null;return{title,sub,icon,sign,dk,col}}
function txRow(t){const v=txView(t);const amt=t.type==='adj'?Math.abs(t.amt):t.amt;return`<button class="tx" data-a="tx" data-v="${t.id}"><span class="ico${v.dk?' dk':''}${v.col?' cico':''}" ${v.col?`style="--c:${v.col}"`:''}>${ic(v.icon)}</span><span><span class="t1">${esc(v.title)}${t.att&&t.att.length?`<span class="mut" aria-label="has attachment">${ic('clip',14)}</span>`:''}</span><span class="t2">${esc(v.sub)}</span></span><span class="am${v.sign>0?' pos':''}">${v.sign>0?'+':v.sign<0?'−':''}${fmt(amt)}</span></button>`}
const sorted=()=>S.tx.slice().sort((x,y)=>y.date.localeCompare(x.date)||(y.id>x.id?1:-1));

let tab='home',flt='all',q='',roff=0;
const V={};
V.home=()=>{const p=period(0),s=stats(p),m=money();const used=s.exp/S.bud.all;const up=S.com.map(c=>({c,st:cstat(c,p),d:dueIn(c,p)})).filter(x=>['overdue','today','upcoming'].includes(x.st)).sort((x,y)=>x.d.localeCompare(y.d)).slice(0,3);const h=T.getHours();
return`<header class="top"><div><p class="mut">${h<12?'Good morning':h<17?'Good afternoon':'Good evening'}${U.name?', '+esc(U.name.split(' ')[0]):''} · ${p.label}</p><h1>Overview</h1></div><button class="icb" data-a="settings" aria-label="Settings">${ic('gear')}</button></header>
<section class="hero"><p class="mut">Total balance</p><p class="big">${sfmt(m.avail)}</p><div class="split"><div><p class="mut">Free to spend</p><p>${sfmt(m.free)}</p></div><div><p class="mut">Still to pay this month</p><p>${fmt(m.left)}</p></div><div><p class="mut">In</p><p>+${fmt(s.inc)}</p></div><div><p class="mut">Out</p><p>−${fmt(s.exp)}</p></div></div></section>
${S.tx.length?'':`<div class="card"><b style="font-size:16px">Let’s set up your money</b><p class="mut" style="margin-top:4px">1. Add your banks and wallets with today’s balance. 2. Set your Cash balance. 3. Add EMIs and bills in Plan. Then record each expense with +.</p><div class="row2"><button class="btn" data-a="addAcc">${ic('plus',18)} Add account</button><button class="btn gh" data-a="acc" data-v="${S.acc[0]?S.acc[0].id:''}">Set cash</button></div></div>`}<button class="card" data-a="tab" data-v="plan" style="width:100%;text-align:left;display:block"><div class="kv"><span><b style="font-size:15px">Monthly budget</b></span><b class="${used>1?'warn':''}">${fmt(s.exp)} <span class="mut" style="display:inline">of ${fmt(S.bud.all)}</span></b></div><div class="bar${used>1?' over':used>=.8?' near':''}"><i style="width:${Math.min(100,used*100)}%"></i></div><p class="mut" style="margin-top:8px">${used>=1?`Over budget by ${fmt(s.exp-S.bud.all)}`:used>=.8?`<span class="near-t">${Math.round(used*100)}% used, slow down</span>`:`${fmt(S.bud.all-s.exp)} left for ${p.label}`}</p></button>
<div class="hd"><h2>Coming up</h2><button class="lk" data-a="tab" data-v="plan">Plan</button></div>
<div class="card" style="padding:4px 16px">${up.length?up.map(x=>comRow(x.c,p,true)).join(''):(S.com.length?'<p class="empty">All dues paid this month.</p>':'<p class="empty">No EMIs or bills yet. Add them in Plan.</p>')}</div>
<div class="hd"><h2>Recent</h2><button class="lk" data-a="tab" data-v="activity">See all</button></div>
<div class="card" style="padding:4px 16px">${sorted().slice(0,5).map(txRow).join('')||'<p class="empty">No transactions yet. Tap + to add one.</p>'}</div>`};
function comRow(c,p,compact){const st=cstat(c,p),d=dueIn(c,p),a=accOf(c.acc);const unpaid=['overdue','today','upcoming'].includes(st);const emi=c.type==='EMI'?`<div class="bar" style="height:5px"><i style="width:${c.done/c.total*100}%"></i></div><div class="prog"><span>${c.done} of ${c.total} paid</span><span>${fmt((c.total-c.done)*c.amt)} left</span></div>`:'';
return`<div class="tx" style="grid-template-columns:42px minmax(0,1fr) auto"><button class="ico cico" data-a="com" data-v="${c.id}" aria-label="${esc(c.name)} details" style="border:0;--c:${catOf(c.cat).c}">${ic(catOf(c.cat).i)}</button><button data-a="com" data-v="${c.id}" style="border:0;background:none;text-align:left;padding:0"><span class="t1">${esc(c.name)}</span><span class="t2 ${st==='overdue'?'warn':''}">${st==='overdue'?'Overdue since':'Due'} ${dshort(d)} · ${c.variable?'about ':''}${fmt(c.amt)}</span>${compact?'':`<span class="t2">${c.type} · ${esc(a.name)}</span>`}${compact?'':emi}</button><span>${unpaid?`<button class="pay" data-a="pay" data-v="${c.id}">Pay</button>`:PILL[st]}</span></div>`}

V.activity=()=>`<header class="top"><div><p class="mut">${S.tx.length} transactions</p><h1>Activity</h1></div></header>
<label class="srch">${ic('search',18)}<input id="q" type="search" placeholder="Search notes, people, accounts" value="${esc(q)}" aria-label="Search"></label>
<div class="chips">${[['all','All'],['exp','Expenses'],['inc','Income'],['tr','Transfers'],['lb','Lend & borrow'],['att','With slip or bill']].concat(CATS.some(c=>c.id===flt)?[[flt,catOf(flt).n]]:[]).map(f=>`<button class="chip${flt===f[0]?' on':''}" data-a="flt" data-v="${f[0]}">${f[1]}</button>`).join('')}</div>
<div id="al">${actList()}</div>`;
function actList(){const qq=q.trim().toLowerCase();const L=sorted().filter(t=>{if(flt==='exp'&&t.type!=='exp')return false;if(flt==='inc'&&t.type!=='inc')return false;if(flt==='tr'&&t.type!=='tr')return false;if(flt==='lb'&&!['lend','borrow','repayIn','repayOut'].includes(t.type))return false;if(flt==='att'&&!(t.att&&t.att.length))return false;if(CATS.some(c=>c.id===flt)&&t.cat!==flt)return false;if(qq){const v=txView(t);if(!(v.title+' '+v.sub+' '+(t.person||'')+' '+t.amt).toLowerCase().includes(qq))return false}return true});
if(!L.length)return'<p class="empty">Nothing matches. Try another filter.</p>';const g={};for(const t of L)(g[t.date]=g[t.date]||[]).push(t);
return Object.keys(g).map(d=>{const out=g[d].filter(t=>t.type==='exp').reduce((s,t)=>s+t.amt,0);return`<div class="day"><span>${dlong(d)}</span><span>${out?'−'+fmt(out):''}</span></div><div class="card" style="padding:2px 16px;margin-top:6px">${g[d].map(txRow).join('')}</div>`}).join('')}

V.plan=()=>{const p=period(0),m=money(),s=stats(p);const L=S.com.slice().sort((x,y)=>ORDER[cstat(x,p)]-ORDER[cstat(y,p)]||dueIn(x,p).localeCompare(dueIn(y,p)));const cats=Object.keys(S.bud.cat).filter(k=>S.bud.cat[k]>0);
return`<header class="top"><div><p class="mut">${p.label}</p><h1>Plan</h1></div><button class="icb" data-a="addCom" aria-label="Add commitment">${ic('plus')}</button></header>
<div class="sum3"><div><p class="mut">Committed</p><p>${fmt(m.left+m.paid)}</p></div><div><p class="mut">Paid</p><p>${fmt(m.paid)}</p></div><div><p class="mut">Left to pay</p><p>${fmt(m.left)}</p></div></div>
<div class="card"><div class="kv"><span>Free to spend after dues</span><b style="font-size:20px">${sfmt(m.free)}</b></div><p class="mut" style="margin-top:4px">Total balance ${sfmt(m.avail)} minus ${fmt(m.left)} still due.</p></div>
<div class="hd"><h2>EMIs, rent and bills</h2><span class="mut">${S.com.length}</span></div>
<div class="card" style="padding:4px 16px">${L.map(c=>comRow(c,p,false)).join('')||'<p class="empty">No commitments yet. Add your EMIs and bills so they are planned.</p>'}</div>
<button class="btn gh" data-a="addCom">${ic('plus',18)} Add EMI, bill or subscription</button>
<div class="hd"><h2>Budget</h2><button class="lk" data-a="budget">Edit</button></div>
<div class="card"><div class="kv"><b>Overall</b><b class="${s.exp>S.bud.all?'warn':''}">${fmt(s.exp)} / ${fmt(S.bud.all)}</b></div><div class="bar${s.exp>S.bud.all?' over':''}"><i style="width:${Math.min(100,s.exp/S.bud.all*100)}%"></i></div><p class="mut" style="margin-top:6px">Includes paid EMIs. Change in Edit.</p>
${cats.map(k=>{const v=s.cat[k]||0,lim=S.bud.cat[k];return`<div style="margin-top:14px"><div class="kv"><span>${catOf(k).n}</span><b class="${v>lim?'warn':v>=lim*.8?'near-t':''}">${fmt(v)} / ${fmt(lim)}</b></div><div class="bar${v>lim?' over':v>=lim*.8?' near':''}"><i style="width:${Math.min(100,v/lim*100)}%"></i></div></div>`}).join('')}</div>`};

const shade=(i,n)=>`color-mix(in srgb,var(--ink) ${Math.round(100-i*(78/Math.max(1,n-1)))}%,var(--card))`;
V.reports=()=>{const p=period(roff),pv=period(roff-1),s=stats(p),sv=stats(pv);const cats=Object.entries(s.cat).sort((x,y)=>y[1]-x[1]);const d=s.exp-sv.exp;
let off=0;const C=2*Math.PI*62;const arcs=cats.map(([k,v],i)=>{const len=v/s.exp*C;const el=`<circle cx="80" cy="80" r="62" fill="none" stroke-width="26" style="stroke:${catOf(k).c}" stroke-dasharray="${Math.max(0,len-1.5)} ${C}" stroke-dashoffset="${-off}" transform="rotate(-90 80 80)"/>`;off+=len;return el}).join('');
const days=[];for(let x=p.a;x<p.b;x=addD(x,1))days.push(x);const mx=Math.max(1,...days.map(x=>s.day[x]||0));
const accs=Object.entries(s.acc).sort((x,y)=>y[1]-x[1]);const srcs=Object.entries(s.src).sort((x,y)=>y[1]-x[1]);
return`<header class="top"><div><p class="mut">Where your money goes</p><h1>Reports</h1></div></header>
<div class="seg" style="align-items:center"><button data-a="rp" data-v="-1" aria-label="Previous month" style="flex:none;width:44px">${ic('cl',18)}</button><b style="flex:1;text-align:center;font-size:15px">${p.label}</b><button data-a="rp" data-v="1" aria-label="Next month" style="flex:none;width:44px" ${roff>=0?'disabled':''}>${ic('cr',18)}</button></div>
<div class="card"><p class="mut">Spent</p><p class="big" style="font-size:34px">${fmt(s.exp)}</p><p class="mut">${sv.exp?`${d>0?'▲':'▼'} ${fmt(d)} ${d>0?'more':'less'} than ${pv.short}`:'No data for the month before'} · Income ${fmt(s.inc)}</p>
${cats.length?`<div class="donut" style="margin-top:14px"><svg width="160" height="160" viewBox="0 0 160 160" role="img" aria-label="Spending by category">${arcs}<text x="80" y="76" text-anchor="middle" font-size="13" fill="currentColor" opacity=".6">Top</text><text x="80" y="96" text-anchor="middle" font-size="16" font-weight="700" fill="currentColor">${catOf(cats[0][0]).s}</text></svg><div class="lg">${cats.slice(0,6).map(([k,v],i)=>`<div><i style="background:${catOf(k).c}"></i><span>${catOf(k).s}</span><b>${Math.round(v/s.exp*100)}%</b></div>`).join('')}</div></div>`:'<p class="empty">No spending in this period.</p>'}</div>
<div class="hd"><h2>By category</h2><span class="mut">vs ${pv.short}</span></div>
<div class="card" style="padding:4px 16px">${cats.map(([k,v])=>{const pr=sv.cat[k]||0,dd=v-pr;return`<button class="tx" data-a="catf" data-v="${k}">${cic(k)}<span><span class="t1">${catOf(k).n}</span><span class="bar" style="height:5px;margin-top:6px;display:block"><i style="width:${v/cats[0][1]*100}%;background:${catOf(k).c}"></i></span></span><span class="am">${fmt(v)}<small>${pr?(dd>=0?'+':'−')+fmt(dd):'new'}</small></span></button>`}).join('')||'<p class="empty">Nothing yet.</p>'}</div>
<div class="hd"><h2>Daily spending</h2><span class="mut">peak ${fmt(mx)}</span></div>
<div class="card"><div class="days">${days.map(x=>`<div class="${x>TODAY?'f':''}" style="height:${(s.day[x]||0)/mx*100}%" title="${dshort(x)}: ${fmt(s.day[x]||0)}"></div>`).join('')}</div><div class="ax"><span>${dshort(p.a)}</span><span>${dshort(days[days.length-1])}</span></div></div>
<div class="hd"><h2>Paid from</h2></div>
<div class="card">${accs.map(([k,v])=>`<div style="margin:6px 0 12px"><div class="kv"><span>${esc(accOf(k).name)}</span><b>${fmt(v)}</b></div><div class="bar"><i style="width:${v/accs[0][1]*100}%"></i></div></div>`).join('')||'<p class="empty">Nothing yet.</p>'}</div>
<div class="hd"><h2>Income by source</h2></div>
<div class="card">${srcs.map(([k,v])=>`<div class="kv" style="padding:8px 0"><span>${catOf(k).n}</span><b>${fmt(v)}</b></div>`).join('')||'<p class="empty">No income in this period.</p>'}</div>`};

V.accounts=()=>{const m=money(),pp=people();const om=Object.entries(pp).filter(x=>x[1]>0),io=Object.entries(pp).filter(x=>x[1]<0);
return`<header class="top"><div><p class="mut">Where your money sits</p><h1>Accounts</h1></div><button class="icb" data-a="addAcc" aria-label="Add account">${ic('plus')}</button></header>
<section class="hero"><p class="mut">Net worth</p><p class="big">${sfmt(m.net)}</p><div class="split"><div><p class="mut">In accounts</p><p>${fmt(m.liquid)}</p></div><div><p class="mut">Card owed</p><p>${fmt(m.owedCard)}</p></div><div><p class="mut">Owed to me</p><p>+${fmt(m.owedMe)}</p></div><div><p class="mut">I owe</p><p>−${fmt(m.iOwe)}</p></div></div></section>
${['bank','wallet','cash','card'].map(ty=>{const L=S.acc.filter(a=>a.type===ty&&!a.archived);if(!L.length)return'';return`<div class="hd"><h2>${ATYPE[ty][0]}${ty==='card'?'s':ty==='cash'?'':'s'}</h2></div>${L.map(a=>{const b=bal(a);return`<button class="acc" data-a="acc" data-v="${a.id}"><span class="ico">${ic(ATYPE[a.type][1])}</span><span><span class="t1">${esc(a.name)}${S.set.def===a.id?' <span class="pill">Default</span>':''}</span><span class="t2">${a.type==='card'?'Amount owed':ATYPE[a.type][0]}</span></span><span class="am" style="font-size:17px">${a.type==='card'?fmt(b):sfmt(b)}</span></button>`}).join('')}`}).join('')}
<div class="row2" style="margin-top:12px"><button class="btn gh" data-a="addT" data-v="tr">${ic('swap',18)} Transfer</button><button class="btn gh" data-a="addT" data-v="lend">${ic('hand',18)} Lend / borrow</button></div>
<div class="hd"><h2>Owed to me</h2><span class="mut">${fmt(m.owedMe)}</span></div>
<div class="card" style="padding:4px 16px">${om.map(([n,v])=>personRow(n,v)).join('')||'<p class="empty">Nobody owes you money.</p>'}</div>
<div class="hd"><h2>I owe</h2><span class="mut">${fmt(m.iOwe)}</span></div>
<div class="card" style="padding:4px 16px">${io.map(([n,v])=>personRow(n,v)).join('')||'<p class="empty">You don\'t owe anyone.</p>'}</div>`};
const personRow=(n,v)=>`<button class="tx" data-a="settle" data-v="${esc(n)}"><span class="ico dk">${ic('user')}</span><span><span class="t1">${esc(n)}</span><span class="t2">${v>0?'Owes you':'You owe'} · tap to record repayment</span></span><span class="am">${fmt(v)}</span></button>`;

const view=document.getElementById('view'),ph=document.getElementById('ph');
const TABS=[['home','Home','home'],['activity','Activity','list'],['plan','Plan','cal'],['reports','Reports','pie'],['accounts','Accounts','wallet']];
function render(keep){const st=view.scrollTop;view.innerHTML=V[tab]();document.getElementById('nav').innerHTML=TABS.map(t=>`<button class="${tab===t[0]?'on':''}" data-a="tab" data-v="${t[0]}" aria-label="${t[1]}">${ic(t[2],22)}${t[1]}</button>`).join('');if(keep)view.scrollTop=st;const qi=document.getElementById('q');if(qi)qi.oninput=e=>{q=e.target.value;document.getElementById('al').innerHTML=actList()}}
document.querySelector('.fab').innerHTML=ic('plus',28,2.2);

let tt,undoFn;const toastEl=document.getElementById('toast');
function toast(msg,undo){document.getElementById('tm').textContent=msg;undoFn=undo;document.getElementById('tu').style.display=undo?'':'none';toastEl.classList.add('on');clearTimeout(tt);tt=setTimeout(()=>toastEl.classList.remove('on'),undo?5000:2600)}
document.getElementById('tu').onclick=()=>{if(undoFn){undoFn();undoFn=null;save();render(1);toastEl.classList.remove('on');toast('Undone')}};

const sheets=[];
function sheet(html,o={}){const w=document.createElement('div');w.className='sw';w.innerHTML=`<div class="scrim"></div><div class="sheet ${o.full?'full':''} ${o.cls||''}" role="dialog" aria-modal="true"><div class="grab"></div><div class="sc">${html}</div></div>`;w.querySelector('.sc').style.cssText='display:flex;flex-direction:column;min-height:0;flex:1';ph.appendChild(w);sheets.push(w);w.querySelector('.scrim').onclick=()=>closeSheet();requestAnimationFrame(()=>requestAnimationFrame(()=>w.classList.add('on')));return w}
function closeSheet(){const w=sheets.pop();if(!w)return;w.classList.remove('on');setTimeout(()=>w.remove(),320)}
const top=()=>sheets[sheets.length-1];
const head=(t,right='')=>`<div class="shh"><button class="icb" data-a="close" aria-label="Close">${ic('x',18)}</button><h3>${t}</h3><span style="width:44px;display:flex;justify-content:flex-end">${right}</span></div>`;

const REG={};
const thumbs=(arr,rm)=>`<div class="atts">${arr.map((x,i)=>{REG[x.id]=x;return`<span style="position:relative"><button class="th" data-a="view" data-v="${x.id}" aria-label="View ${esc(x.label)}">${x.pdf?'<span class="pdf">PDF</span>':`<img src="${x.url}" alt="">`}${rm?'':`<span>${esc(x.label)}</span>`}</button>${rm?`<button class="tl" data-a="albl" data-v="${i}" aria-label="Switch label">${esc(x.label==='Payment slip'?'Slip':x.label)} ⇄</button><button class="rm" data-a="${rm}" data-v="${i}" aria-label="Remove">${ic('x',12,2.4)}</button>`:''}</span>`}).join('')}</div>`;
const fi=document.getElementById('fi');let attTarget=null;
function pick(label,arr,cb){attTarget={label,arr,cb};fi.value='';fi.click()}
fi.onchange=()=>{const fs=[...fi.files];if(!attTarget||!fs.length)return;let n=fs.length;for(const f of fs){if(f.size>10*1024*1024){toast('File over 10 MB skipped');if(--n===0)attTarget.cb();continue}const r=new FileReader();r.onload=()=>{attTarget.arr.push({id:nid(),label:attTarget.label,url:r.result,name:f.name,pdf:f.type==='application/pdf'});if(--n===0)attTarget.cb()};r.readAsDataURL(f)}};

let A=null;
function openAdd(type='exp',pre){A=Object.assign({type,amt:'',cat:null,acc:S.set.def,to:null,date:TODAY,note:'',person:'',dir:'lent',att:[],fee:'',edit:null,cid:null},pre||{});if(type==='tr'&&!A.to)A.to=S.acc.find(a=>a.id!==A.acc&&a.type!=='card')?.id;sheet(addHTML(),{full:true,cls:'add'});bindAdd()}
const fa=t=>S.acc.find(a=>a.type===t&&!a.archived);
const TL={exp:'Expense',inc:'Income',tr:'Transfer',lend:'Lend'};
function addHTML(){return`<div class="shh"><button class="icb" data-a="close" aria-label="Close">${ic('x',18)}</button><div class="seg" style="flex:1">${Object.keys(TL).map(k=>`<button class="${A.type===k?'on':''}" data-a="aty" data-v="${k}">${TL[k]}</button>`).join('')}</div></div>
<div class="amt" id="amtbox"><span>Rs</span><b id="amt" class="${A.amt?'':'z'}">${A.amt?Number(A.amt.split('.')[0]).toLocaleString('en-IN')+(A.amt.includes('.')?'.'+A.amt.split('.')[1]:''):'0'}</b></div>
<div class="shb" id="addb">${addBody()}</div>
<div class="kp">${['1','2','3','4','5','6','7','8','9','.','0','⌫'].map(k=>`<button data-a="key" data-v="${k}" aria-label="${k==='⌫'?'Delete':k}">${k==='⌫'?ic('del',22):k}</button>`).join('')}</div>
<div class="foot"><button class="btn" data-a="saveAdd" style="margin-top:8px">${A.edit?'Save changes':A.type==='exp'?'Save expense':A.type==='inc'?'Save income':A.type==='tr'?'Save transfer':A.dir==='lent'?'Save money lent':'Save money borrowed'}</button></div>`}
const accChips=(key,label,excl)=>`<span class="l">${label}</span><div class="chips">${S.acc.filter(a=>!a.archived&&a.id!==excl&&!(key==='to'&&A.type==='tr'&&false)).map(a=>`<button class="chip${A[key]===a.id?' on':''}" data-a="aacc" data-k="${key}" data-v="${a.id}">${ic(ATYPE[a.type][1],18)}<span>${esc(a.name)}<small>${a.type==='card'?'owed '+fmt(bal(a)):sfmt(bal(a))}</small></span></button>`).join('')}</div>`;
function dateRow(){const y=addD(TODAY,-1);return`<span class="l">Date</span><div class="chips"><button class="chip${A.date===TODAY?' on':''}" data-a="adate" data-v="${TODAY}">Today</button><button class="chip${A.date===y?' on':''}" data-a="adate" data-v="${y}">Yesterday</button><label class="chip${A.date!==TODAY&&A.date!==y?' on':''}" style="position:relative">${ic('cal',18)} ${A.date!==TODAY&&A.date!==y?dshort(A.date):'Pick date'}<input type="date" id="adate" value="${A.date}" max="${TODAY}" style="position:absolute;inset:0;opacity:0" aria-label="Pick date"></label></div>`}
const noteRow=(ph)=>`<span class="l">Note</span><input class="in" id="anote" value="${esc(A.note)}" placeholder="${ph}" autocomplete="off">`;
const attRow=()=>`<span class="l">Bill or payment slip (optional)</span><button class="drop" data-a="aatt"><span class="ico dk">${ic('cam',22)}</span><span><b>Add photo or file</b><small>Take a photo, or choose a screenshot or PDF</small></span></button>${A.att.length?thumbs(A.att,'armatt'):''}${A.att.length?'<p class="mut" style="margin-top:6px;font-size:13px">Tap the label to switch between Bill and Payment slip.</p>':''}`;
function addBody(){if(A.type==='exp'||A.type==='inc'){const L=A.type==='exp'?CATS:SRCS;return`${A.cid?`<p class="pill dk" style="margin:6px 0 0">Paying ${esc(S.com.find(c=>c.id===A.cid)?.name||'')}</p>`:''}<span class="l">${A.type==='exp'?'Category':'Source'}</span><div class="cg">${L.map(c=>`<button class="${A.cat===c.id?'on':''}" data-a="acat" data-v="${c.id}"><span class="ico cico" style="--c:${c.c}">${ic(c.i)}</span>${c.s}</button>`).join('')}</div>${accChips('acc',A.type==='exp'?'Paid from':'Received in')}${A.type==='inc'?`<span class="l">From whom (optional)</span><input class="in" id="aperson" value="${esc(A.person)}" placeholder="e.g. Didi, employer, tenant">`:''}${dateRow()}${noteRow(A.type==='exp'?'e.g. Momo at Newroad':'e.g. November salary')}${attRow()}`}
if(A.type==='tr')return`<div class="chips" style="margin-top:8px">${[['ATM withdrawal','bank','cash'],['Load wallet','bank','wallet'],['Pay credit card','bank','card']].filter(s=>fa(s[1])&&fa(s[2])).map(s=>[s[0],fa(s[1]).id,fa(s[2]).id]).map(s=>`<button class="chip" data-a="short" data-v="${s[0]}|${s[1]}|${s[2]}">${s[0]}</button>`).join('')}</div>${accChips('acc','From')}${accChips('to','To',A.acc)}${dateRow()}<span class="l">Fee (optional)</span><input class="in" id="afee" inputmode="decimal" value="${esc(A.fee)}" placeholder="Saved as a separate Bank & fees expense">${noteRow('e.g. ATM withdrawal')}<p class="mut" style="font-size:13px;margin-top:10px">Transfers move money between your accounts. They are not counted as spending or income.</p>`;
const pp=Object.keys(people());return`<span class="l">Direction</span><div class="seg"><button class="${A.dir==='lent'?'on':''}" data-a="adir" data-v="lent">I lent money</button><button class="${A.dir==='borrowed'?'on':''}" data-a="adir" data-v="borrowed">I borrowed money</button></div><span class="l">${A.dir==='lent'?'Lent to':'Borrowed from'}</span><input class="in" id="aperson" value="${esc(A.person)}" placeholder="Person's name">${pp.length?`<div class="chips" style="margin-top:8px">${pp.map(n=>`<button class="chip${A.person===n?' on':''}" data-a="aper" data-v="${esc(n)}">${ic('user',16)} ${esc(n)}</button>`).join('')}</div>`:''}${accChips('acc',A.dir==='lent'?'Paid from':'Received in')}${dateRow()}${noteRow('e.g. For bike repair')}${attRow()}<p class="mut" style="font-size:13px;margin-top:10px">Shows under ${A.dir==='lent'?'Owed to me':'I owe'} in Accounts until repaid. Not counted as spending or income.</p>`}
function bindAdd(){const w=top();const b=w.querySelector('#addb');const sh=w.querySelector('.sheet');
  b.querySelectorAll('input').forEach(el=>{el.addEventListener('focus',()=>{if(el.type!=='date')sh.classList.add('typing')});el.addEventListener('blur',()=>sh.classList.remove('typing'))});
  const on=(id,f)=>{const el=b.querySelector('#'+id);if(el)el.oninput=e=>f(e.target.value)};
  on('anote',v=>A.note=v);on('aperson',v=>A.person=v);on('afee',v=>A.fee=v.replace(/[^\d.]/g,''));
  const d=b.querySelector('#adate');if(d)d.onchange=e=>{if(e.target.value){A.date=e.target.value;reAdd()}}}
function reAdd(full){const w=top();if(full){w.querySelector('.sc').innerHTML=addHTML()}else{const b=w.querySelector('#addb'),st=b.scrollTop;b.innerHTML=addBody();b.scrollTop=st}bindAdd()}
function amtShow(){const el=top().querySelector('#amt');const[i,f]=A.amt.split('.');el.textContent=A.amt?Number(i||0).toLocaleString('en-IN')+(A.amt.includes('.')?'.'+f:''):'0';el.className=A.amt?'':'z'}
function saveAdd(){const amt=parseFloat(A.amt);const bad=m=>{toast(m);const x=top().querySelector('#amtbox');x.classList.remove('shake');void x.offsetWidth;x.classList.add('shake')};
  if(!(amt>0))return bad('Enter an amount first');
  if((A.type==='exp'||A.type==='inc')&&!A.cat)return bad(A.type==='exp'?'Pick a category':'Pick an income source');
  if(!A.acc)return bad('Pick an account');
  if(A.type==='tr'&&(!A.to||A.to===A.acc))return bad('Pick a different To account');
  if(A.type==='lend'&&!A.person.trim())return bad('Add the person\'s name');
  const type=A.type==='lend'?(A.dir==='lent'?'lend':'borrow'):A.type;
  const t={id:A.edit||nid(),type,amt,acc:A.acc,date:A.date,note:A.note.trim(),att:A.att};
  if(type==='exp'||type==='inc')t.cat=A.cat;if(type==='tr')t.to=A.to;if(A.person.trim())t.person=A.person.trim();if(A.cid)t.cid=A.cid;
  const added=[t];const fee=parseFloat(A.fee);if(type==='tr'&&fee>0)added.push({id:nid(),type:'exp',amt:fee,acc:A.acc,date:A.date,cat:'fees',note:'Transfer fee',att:[],lk:t.id});
  let undo;if(A.edit){const i=S.tx.findIndex(x=>x.id===A.edit);const old=S.tx[i];S.tx[i]=t;undo=()=>{S.tx[S.tx.findIndex(x=>x.id===t.id)]=old}}else{S.tx.push(...added);const ids=added.map(x=>x.id);undo=()=>{S.tx=S.tx.filter(x=>!ids.includes(x.id))}}
  let undo2=()=>{};if(A.cid&&!A.edit){const c=S.com.find(x=>x.id===A.cid);const dd=dueIn(c,period(0));if(c&&!c.paid.includes(dd)){c.paid.push(dd);if(c.type==='EMI')c.done=Math.min(c.total,c.done+1);undo2=()=>{c.paid=c.paid.filter(x=>x!==dd);if(c.type==='EMI')c.done--}}}
  save();while(sheets.length)closeSheet();render(1);const a=accOf(A.acc);
  toast(type==='tr'?`Moved ${fmt(amt)} to ${accOf(A.to).name}`:`${A.edit?'Updated':'Saved'} · ${a.name} ${a.type==='card'?'owed':'now'} ${a.type==='card'?fmt(bal(a)):sfmt(bal(a))}`,()=>{undo();undo2()})}

function openTx(id){const t=S.tx.find(x=>x.id===id);if(!t)return;const v=txView(t);const rows=[['Type',{exp:'Expense',inc:'Income',tr:'Transfer',lend:'Money lent',borrow:'Money borrowed',repayIn:'Repayment received',repayOut:'Repayment made',adj:'Balance correction'}[t.type]],['Date',dlong(t.date)],t.cat?[t.type==='inc'?'Source':'Category',catOf(t.cat).n]:null,[t.type==='tr'?'From':t.type==='inc'||t.type==='borrow'||t.type==='repayIn'?'Received in':'Paid from',accOf(t.acc).name],t.to?['To',accOf(t.to).name]:null,t.person?['Person',t.person]:null,t.note?['Note',t.note]:null,t.cid?['Commitment',S.com.find(c=>c.id===t.cid)?.name||'']:null].filter(Boolean);
  const edit=['exp','inc','tr','lend','borrow'].includes(t.type);
  sheet(`${head('Transaction')}<div class="shb"><div style="text-align:center;padding:6px 0 14px"><span class="ico${v.dk?' dk':''}" style="margin:0 auto;width:54px;height:54px;border-radius:18px">${ic(v.icon,24)}</span><p class="big" style="margin-top:10px">${v.sign>0?'+':v.sign<0?'−':''}${fmt(Math.abs(t.amt))}</p><p class="mut">${esc(v.title)}</p></div><div class="card" style="padding:4px 16px">${rows.map(r=>`<div class="kv" style="padding:11px 0;border-bottom:1px solid var(--line)"><span class="mut">${r[0]}</span><b style="text-align:right;white-space:normal">${esc(r[1])}</b></div>`).join('')}</div>
  <span class="l">Bill and payment slip</span>${t.att&&t.att.length?thumbs(t.att):'<p class="mut" style="font-size:13px">No attachment.</p>'}<button class="btn gh" data-a="txatt" data-v="${t.id}">${ic('clip',18)} Attach bill or slip</button>
  <div class="row2">${edit?`<button class="btn gh" data-a="edit" data-v="${t.id}">Edit</button>`:''}<button class="btn wr" data-a="del" data-v="${t.id}" style="${edit?'':'grid-column:span 2'}">${ic('trash',18)} Delete</button></div></div>`)}

function openPay(cid){const c=S.com.find(x=>x.id===cid);openAdd('exp',{amt:String(c.amt),cat:c.cat,acc:c.acc,note:c.name,cid:c.id})}
function openCom(cid){const c=S.com.find(x=>x.id===cid),p=period(0),st=cstat(c,p),d=dueIn(c,p);const hist=S.tx.filter(t=>t.cid===c.id).sort((x,y)=>y.date.localeCompare(x.date));
  sheet(`${head(esc(c.name))}<div class="shb"><div class="card"><div class="kv"><span class="mut">${c.type}${c.lender?' · '+esc(c.lender):''}</span>${PILL[st]}</div><p class="big" style="font-size:32px">${c.variable?'about ':''}${fmt(c.amt)}</p><p class="mut">Due ${dshort(d)} · every month on day ${c.due} · from ${esc(accOf(c.acc).name)}</p>${c.type==='EMI'?`<div class="bar"><i style="width:${c.done/c.total*100}%"></i></div><div class="prog"><span>${c.done} of ${c.total} instalments</span><span>${fmt((c.total-c.done)*c.amt)} remaining</span></div>`:''}<p class="mut" style="margin-top:8px">Reminder ${c.remind} days before and on the due day.</p></div>
  ${['overdue','today','upcoming'].includes(st)?`<button class="btn" data-a="pay" data-v="${c.id}">Mark as paid</button><div class="row2"><button class="btn gh" data-a="later" data-v="${c.id}">Remind tomorrow</button><button class="btn gh" data-a="skip" data-v="${c.id}">Skip this month</button></div>`:''}
  <div class="hd"><h2>Payment history</h2></div><div class="card" style="padding:4px 16px">${hist.map(txRow).join('')||'<p class="empty">No payments recorded yet.</p>'}</div>
  <button class="btn wr" data-a="delCom" data-v="${c.id}">${ic('trash',18)} Delete commitment</button><p class="mut" style="font-size:13px;margin-top:8px">Deleting keeps past payments in Activity.</p></div>`)}

let NC=null;
function openAddCom(){NC={name:'',type:'EMI',amt:'',cat:'emi',acc:S.set.def,due:Math.min(28,T.getDate()+3),total:'',done:'0',lender:'',variable:false,remind:2};sheet(`${head('New commitment')}<div class="shb" id="ncb">${ncBody()}</div><div class="foot"><button class="btn" data-a="saveCom">Save commitment</button></div>`,{full:true});bindNC()}
function ncBody(){return`<span class="l">Type</span><div class="chips">${CTYPE.map(t=>`<button class="chip${NC.type===t?' on':''}" data-a="nct" data-v="${t}">${t}</button>`).join('')}</div>
<span class="l">Name</span><input class="in" id="nc_name" value="${esc(NC.name)}" placeholder="${NC.type==='EMI'?'e.g. Bike loan':NC.type==='Bill'?'e.g. Electricity':'e.g. Flat rent'}">
<div class="row2"><div><span class="l">${NC.variable?'Estimated amount':'Amount'} (Rs)</span><input class="in" id="nc_amt" inputmode="decimal" value="${esc(NC.amt)}" placeholder="0"></div><div><span class="l">Due day each month</span><select class="in" id="nc_due">${Array.from({length:28},(_,i)=>`<option ${NC.due===i+1?'selected':''}>${i+1}</option>`).join('')}</select></div></div>
<label class="chip" style="margin-top:12px;width:100%"><input type="checkbox" id="nc_var" ${NC.variable?'checked':''} style="width:20px;height:20px;accent-color:var(--pri)"> Amount changes each month (enter actual when paying)</label>
${NC.type==='EMI'?`<div class="row2"><div><span class="l">Total instalments</span><input class="in" id="nc_total" inputmode="numeric" value="${esc(NC.total)}" placeholder="e.g. 36"></div><div><span class="l">Already paid</span><input class="in" id="nc_done" inputmode="numeric" value="${esc(NC.done)}"></div></div><span class="l">Lender</span><input class="in" id="nc_lender" value="${esc(NC.lender)}" placeholder="e.g. Prabhu Bank">`:''}
<span class="l">Category</span><select class="in" id="nc_cat">${CATS.map(c=>`<option value="${c.id}" ${NC.cat===c.id?'selected':''}>${c.n}</option>`).join('')}</select>
<span class="l">Pay from</span><div class="chips">${S.acc.filter(a=>!a.archived).map(a=>`<button class="chip${NC.acc===a.id?' on':''}" data-a="ncacc" data-v="${a.id}">${ic(ATYPE[a.type][1],18)} ${esc(a.name)}</button>`).join('')}</div>
<span class="l">Remind me</span><div class="chips">${[1,2,3,5].map(n=>`<button class="chip${NC.remind===n?' on':''}" data-a="ncrem" data-v="${n}">${n} day${n>1?'s':''} before</button>`).join('')}</div>`}
function bindNC(){const b=top().querySelector('#ncb');const map={nc_name:'name',nc_amt:'amt',nc_total:'total',nc_done:'done',nc_lender:'lender'};for(const k in map){const el=b.querySelector('#'+k);if(el)el.oninput=e=>NC[map[k]]=e.target.value}
  b.querySelector('#nc_due').onchange=e=>NC.due=+e.target.value;b.querySelector('#nc_cat').onchange=e=>NC.cat=e.target.value;b.querySelector('#nc_var').onchange=e=>{NC.variable=e.target.checked;reNC()}}
function reNC(){const b=top().querySelector('#ncb'),st=b.scrollTop;b.innerHTML=ncBody();b.scrollTop=st;bindNC()}
function saveCom(){const amt=parseFloat(NC.amt);if(!NC.name.trim())return toast('Give it a name');if(!(amt>0))return toast('Enter the amount');if(NC.type==='EMI'&&!(+NC.total>0))return toast('Enter total instalments');
  const c={id:nid(),name:NC.name.trim(),type:NC.type,amt,cat:NC.cat,acc:NC.acc,due:NC.due,variable:NC.variable,remind:NC.remind,paid:[],skip:[]};if(NC.type==='EMI'){c.total=+NC.total;c.done=Math.min(c.total,+NC.done||0);c.lender=NC.lender.trim()}
  S.com.push(c);save();closeSheet();tab='plan';render();toast(`${c.name} added · reminder ${c.remind} days before`,()=>{S.com=S.com.filter(x=>x.id!==c.id)})}

function openAcc(id){const a=S.acc.find(x=>x.id===id),p=period(0);const L=sorted().filter(t=>t.acc===id||t.to===id);const inn=L.filter(t=>inP(t,p)).reduce((s,t)=>s+Math.max(0,delta(t,id)),0),out=L.filter(t=>inP(t,p)).reduce((s,t)=>s+Math.min(0,delta(t,id)),0);const b=bal(a);
  sheet(`${head(esc(a.name))}<div class="shb"><div class="card"><p class="mut">${a.type==='card'?'Amount owed':'Current balance'}</p><p class="big">${a.type==='card'?fmt(b):sfmt(b)}</p><div class="kv" style="margin-top:10px"><span class="mut">In this month</span><b>+${fmt(inn)}</b></div><div class="kv" style="margin-top:4px"><span class="mut">Out this month</span><b>−${fmt(out)}</b></div><div class="kv" style="margin-top:4px"><span class="mut">Opening balance</span><b>${sfmt(a.open)}</b></div></div>
  <span class="l">Balance looks wrong? Enter the real one</span><div style="display:flex;gap:8px"><input class="in" id="corr" inputmode="decimal" placeholder="${Math.round(b)}"><button class="pay" style="height:48px" data-a="corr" data-v="${a.id}">Fix</button></div><p class="mut" style="font-size:13px;margin-top:6px">The difference is saved as a correction, not as spending.</p>
  ${S.set.def!==a.id?`<button class="btn gh" data-a="def" data-v="${a.id}">Make default for new expenses</button>`:''}
  <div class="hd"><h2>Transactions</h2><span class="mut">${L.length}</span></div><div class="card" style="padding:4px 16px">${L.slice(0,25).map(txRow).join('')||'<p class="empty">No transactions on this account yet.</p>'}</div>
  <button class="btn wr" data-a="arch" data-v="${a.id}">Archive account</button><p class="mut" style="font-size:13px;margin-top:8px">Archived accounts are hidden; their history stays.</p></div>`)}
let NA=null;
function openAddAcc(){NA={name:'',type:'bank',open:''};sheet(`${head('New account')}<div class="shb" id="nab">${naBody()}</div><div class="foot"><button class="btn" data-a="saveAcc">Add account</button></div>`);bindNA()}
const naBody=()=>`<span class="l">Type</span><div class="cg">${Object.keys(ATYPE).map(k=>`<button class="${NA.type===k?'on':''}" data-a="nat" data-v="${k}"><span class="ico">${ic(ATYPE[k][1])}</span>${ATYPE[k][0]}</button>`).join('')}</div><span class="l">Name</span><input class="in" id="na_name" value="${esc(NA.name)}" placeholder="${NA.type==='wallet'?'e.g. eSewa':NA.type==='card'?'e.g. Visa card':NA.type==='cash'?'e.g. Pocket cash':'e.g. Nabil Bank Savings'}"><span class="l">${NA.type==='card'?'Amount owed now':'Current balance'} (Rs)</span><input class="in" id="na_open" inputmode="decimal" value="${esc(NA.open)}" placeholder="0"><p class="mut" style="font-size:13px;margin-top:8px">From here on the app calculates the balance from what you record.</p>`;
function bindNA(){const b=top().querySelector('#nab');b.querySelector('#na_name').oninput=e=>NA.name=e.target.value;b.querySelector('#na_open').oninput=e=>NA.open=e.target.value}
function saveAcc(){if(!NA.name.trim())return toast('Give the account a name');const v=parseFloat(NA.open)||0;const a={id:nid(),name:NA.name.trim(),type:NA.type,open:NA.type==='card'?-Math.abs(v):v};S.acc.push(a);save();closeSheet();tab='accounts';render();toast(`${a.name} added`,()=>{S.acc=S.acc.filter(x=>x.id!==a.id)})}

let ST=null;
function openSettle(n){const v=people()[n]||0;ST={n,amt:String(Math.abs(Math.round(v))),acc:S.set.def,dir:v>0?'in':'out'};const w=sheet(`${head('Record repayment')}<div class="shb"><div class="card"><p class="mut">${v>0?`${esc(n)} owes you`:`You owe ${esc(n)}`}</p><p class="big">${fmt(v)}</p></div><span class="l">${v>0?'Amount received':'Amount paid back'} (Rs)</span><input class="in" id="st_amt" inputmode="decimal" value="${ST.amt}"><span class="l">${v>0?'Received in':'Paid from'}</span><div class="chips" id="stc">${stChips()}</div><p class="mut" style="font-size:13px;margin-top:10px">Partial amounts are fine; the rest stays outstanding.</p></div><div class="foot"><button class="btn" data-a="saveSt">Save repayment</button></div>`);w.querySelector('#st_amt').oninput=e=>ST.amt=e.target.value}
const stChips=()=>S.acc.filter(a=>!a.archived&&a.type!=='card').map(a=>`<button class="chip${ST.acc===a.id?' on':''}" data-a="stacc" data-v="${a.id}">${ic(ATYPE[a.type][1],18)}<span>${esc(a.name)}<small>${sfmt(bal(a))}</small></span></button>`).join('');
function saveSt(){const amt=parseFloat(ST.amt);if(!(amt>0))return toast('Enter an amount');const t={id:nid(),type:ST.dir==='in'?'repayIn':'repayOut',amt,acc:ST.acc,date:TODAY,person:ST.n,note:'',att:[]};S.tx.push(t);save();closeSheet();render(1);const left=Math.abs(people()[ST.n]||0);toast(left<1?`${ST.n} settled`:`${fmt(left)} still outstanding`,()=>{S.tx=S.tx.filter(x=>x.id!==t.id)})}

function openBudget(){const p=period(0),s=stats(p);sheet(`${head('Budget')}<div class="shb" id="bb"><span class="l">Overall monthly limit (Rs)</span><input class="in" data-b="all" inputmode="decimal" value="${S.bud.all}"><p class="mut" style="font-size:13px;margin-top:6px">Alerts at 80% and 100%. Paid EMIs count toward it.</p><span class="l">Per category (leave empty for no limit)</span>${CATS.map(c=>`<div style="display:grid;grid-template-columns:42px minmax(0,1fr) 120px;gap:10px;align-items:center;margin-top:8px">${cic(c.id)}<span><span class="t1" style="font-size:14px">${c.n}</span><span class="t2">spent ${fmt(s.cat[c.id]||0)}</span></span><input class="in" data-b="${c.id}" inputmode="decimal" value="${S.bud.cat[c.id]||''}" placeholder="No limit" aria-label="${c.n} limit"></div>`).join('')}</div><div class="foot"><button class="btn" data-a="saveBud">Save budget</button></div>`,{full:true})}
function saveBud(){const old=JSON.parse(JSON.stringify(S.bud));top().querySelectorAll('[data-b]').forEach(el=>{const v=parseFloat(el.value);if(el.dataset.b==='all'){if(v>0)S.bud.all=v}else if(v>0)S.bud.cat[el.dataset.b]=v;else delete S.bud.cat[el.dataset.b]});save();closeSheet();render(1);toast('Budget saved',()=>{S.bud=old})}

function openSettings(){sheet(`${head('Settings')}<div class="shb"><span class="l">Account</span><div class="card" style="margin-top:0;display:flex;align-items:center;gap:12px"><span class="ico dk">${ic('user')}</span><span style="flex:1;min-width:0"><span class="t1">${esc(U.name||'Your account')}</span><span class="t2">${esc(U.email)}</span></span><button class="pay" data-a="logout" style="background:var(--soft);color:var(--ink)">Log out</button></div><span class="l">Appearance</span><div class="seg" id="thm">${[['light','Light'],['dark','Dark'],['system','System']].map(t=>`<button class="${S.set.theme===t[0]?'on':''}" data-a="theme" data-v="${t[0]}">${t[1]}</button>`).join('')}</div><p class="mut" style="font-size:13px;margin-top:6px">System follows your phone's light or dark setting.</p><span class="l">Month starts on</span><select class="in" id="ms">${Array.from({length:28},(_,i)=>`<option value="${i+1}" ${S.set.start===i+1?'selected':''}>${i===0?'1st (calendar month)':`Day ${i+1}${i+1===25?' (e.g. payday)':''}`}</option>`).join('')}</select><p class="mut" style="font-size:13px;margin-top:6px">Set it to your payday so "this month" matches your salary cycle. Nothing is lost when you change it.</p>
<span class="l">Default account for new expenses</span><div class="chips">${S.acc.filter(a=>!a.archived).map(a=>`<button class="chip${S.set.def===a.id?' on':''}" data-a="def" data-v="${a.id}">${esc(a.name)}</button>`).join('')}</div>
<span class="l">Currency</span><div class="card" style="margin-top:0"><div class="kv"><span>Nepalese rupee</span><b>Rs</b></div></div>
<span class="l">Your data</span><div class="card" style="margin-top:0"><p style="margin:0;font-size:14px">${Store.mode==='cloud'?'Saved to your account in the cloud. Log in on any phone to see it.':'Local mode: stored in this browser only.'}</p><p class="mut" id="syncst" style="margin-top:6px;font-size:13px">${esc(Store.statusText())}</p></div>
<button class="btn gh" data-a="export">${ic('copy',18)} Export transactions (CSV)</button><button class="btn gh" data-a="budget">Edit budget</button><button class="btn wr" data-a="reset">${U.demo?'Reset demo data':'Clear all my data'}</button></div>`);top().querySelector('#ms').onchange=e=>{S.set.start=+e.target.value;roff=0;save();render();toast(`Month now starts on day ${S.set.start}`)}}
function openExport(){const rows=[['Date','Type','Amount','Account','To','Category','Person','Note','Attachments']].concat(sorted().map(t=>[t.date,t.type,t.amt,accOf(t.acc).name,t.to?accOf(t.to).name:'',t.cat?catOf(t.cat).n:'',t.person||'',t.note||'',(t.att||[]).length]));const csv=rows.map(r=>r.map(v=>/[",\n]/.test(String(v))?`"${String(v).replace(/"/g,'""')}"`:v).join(',')).join('\n');
  sheet(`${head('Export')}<div class="shb"><p class="mut" style="font-size:14px">In the app this saves a backup file you can send to Google Drive, iCloud or email. Here you can copy the CSV.</p><textarea class="in" id="csv" rows="12" readonly style="margin-top:12px">${esc(csv)}</textarea><button class="btn" data-a="copy">${ic('copy',18)} Copy CSV</button></div>`)}

const ACT={
 tab:v=>{tab=v;if(v!=='activity'){}render();view.scrollTop=0},
 add:()=>openAdd('exp'),addT:v=>openAdd(v),close:()=>closeSheet(),settings:openSettings,
 tx:openTx,acc:openAcc,com:openCom,pay:v=>{while(sheets.length)closeSheet();setTimeout(()=>openPay(v),sheets.length?0:0)},addCom:openAddCom,addAcc:openAddAcc,settle:openSettle,budget:()=>{if(sheets.length)closeSheet();setTimeout(openBudget,sheets.length?330:0)},export:openExport,
 flt:v=>{flt=v;render(1)},catf:v=>{flt=v;q='';tab='activity';render()},rp:v=>{roff=Math.min(0,roff+(+v));render(1)},
 aty:v=>{const keep={amt:A.amt,acc:A.acc,date:A.date,note:A.note,att:A.att};A=Object.assign(A,{type:v,cat:null,cid:null},keep);if(v==='tr'&&(!A.to||A.to===A.acc))A.to=S.acc.find(a=>a.id!==A.acc&&a.type!=='card')?.id;reAdd(1)},
 key:v=>{let s=A.amt;if(v==='⌫')s=s.slice(0,-1);else if(v==='.'){if(!s.includes('.'))s=(s||'0')+'.'}else{if(s.includes('.')&&s.split('.')[1].length>=2)return;if(s.replace('.','').length>=9)return;s=s==='0'?v:s+v}A.amt=s;amtShow()},
 acat:v=>{A.cat=v;reAdd()},aacc:(v,el)=>{A[el.dataset.k]=v;if(A.type==='tr'&&A.acc===A.to)A.to=S.acc.find(a=>a.id!==A.acc)?.id;reAdd()},adate:v=>{A.date=v;reAdd()},adir:v=>{A.dir=v;reAdd(1)},aper:v=>{A.person=v;reAdd()},
 short:v=>{const[n,f,t]=v.split('|');A.acc=f;A.to=t;A.note=n;reAdd()},
 aatt:()=>{if(A.att.length>=5)return toast('Up to 5 files per transaction');pick('Payment slip',A.att,()=>{A.att.forEach(x=>{if(x.pdf&&!x.set)x.label='Bill'});reAdd()})},albl:v=>{const x=A.att[+v];x.label=x.label==='Bill'?'Payment slip':'Bill';x.set=1;reAdd()},armatt:v=>{A.att.splice(+v,1);reAdd()},
 saveAdd,view:v=>{const x=REG[v];if(!x)return;sheet(`${head(esc(x.label))}<div class="shb viewer">${x.pdf?`<div class="card" style="text-align:center;padding:40px"><b>PDF</b><p class="mut">${esc(x.name)}</p></div>`:`<img src="${x.url}" alt="${esc(x.label)}">`}</div>`)},
 txatt:v=>{const t=S.tx.find(x=>x.id===v);t.att=t.att||[];pick('Payment slip',t.att,()=>{save();closeSheet();setTimeout(()=>openTx(v),330);render(1);toast('Attached')})},
 edit:v=>{const t=S.tx.find(x=>x.id===v);closeSheet();setTimeout(()=>openAdd(['lend','borrow'].includes(t.type)?'lend':t.type,{amt:String(t.amt),cat:t.cat||null,acc:t.acc,to:t.to||null,date:t.date,note:t.note||'',person:t.person||'',dir:t.type==='borrow'?'borrowed':'lent',att:(t.att||[]).slice(),edit:t.id,cid:t.cid||null}),330)},
 del:(v,el)=>{if(el.dataset.sure!=='1'){el.dataset.sure='1';el.innerHTML='Tap again to delete';return}const t=S.tx.find(x=>x.id===v);const linked=S.tx.filter(x=>x.lk===v);S.tx=S.tx.filter(x=>x.id!==v&&x.lk!==v);let c=null,dd=null;if(t.cid){c=S.com.find(x=>x.id===t.cid);if(c){dd=c.paid.find(d=>d.slice(0,7)===t.date.slice(0,7))||null;if(dd){c.paid=c.paid.filter(x=>x!==dd);if(c.type==='EMI')c.done--}}}save();while(sheets.length)closeSheet();render(1);toast('Transaction deleted',()=>{S.tx.push(t,...linked);if(c&&dd){c.paid.push(dd);if(c.type==='EMI')c.done++}})},
 later:v=>{closeSheet();toast('We\'ll remind you tomorrow at 9:00')},
 skip:v=>{const c=S.com.find(x=>x.id===v),d=dueIn(c,period(0));c.skip.push(d);save();closeSheet();render(1);toast(`${c.name} skipped for this month`,()=>{c.skip=c.skip.filter(x=>x!==d)})},
 delCom:(v,el)=>{if(el.dataset.sure!=='1'){el.dataset.sure='1';el.innerHTML='Tap again to delete';return}const i=S.com.findIndex(x=>x.id===v),c=S.com[i];S.com.splice(i,1);save();closeSheet();render(1);toast(`${c.name} deleted`,()=>{S.com.splice(i,0,c)})},
 nct:v=>{NC.type=v;if(v==='EMI')NC.cat='emi';else if(v==='Rent')NC.cat='rent';else if(v==='Bill')NC.cat='bills';else if(v==='Subscription')NC.cat='fun';else if(v==='Insurance')NC.cat='health';reNC()},ncacc:v=>{NC.acc=v;reNC()},ncrem:v=>{NC.remind=+v;reNC()},saveCom,
 nat:v=>{NA.type=v;const b=top().querySelector('#nab');b.innerHTML=naBody();bindNA()},saveAcc,
 stacc:v=>{ST.acc=v;top().querySelector('#stc').innerHTML=stChips()},saveSt,saveBud,
 theme:v=>{S.set.theme=v;save();applyTheme();top().querySelectorAll('#thm button').forEach(b=>b.classList.toggle('on',b.dataset.v===v));toast(v==='system'?'Theme follows your phone':`${v[0].toUpperCase()+v.slice(1)} theme on`)},
 corr:v=>{const a=S.acc.find(x=>x.id===v),el=top().querySelector('#corr'),real=parseFloat(el.value);if(isNaN(real))return toast('Enter the real balance');const b=bal(a),target=a.type==='card'?-Math.abs(real):real,diff=target-b;if(Math.abs(diff)<.01)return toast('Already correct');const t={id:nid(),type:'adj',amt:diff,acc:v,date:TODAY,note:'',att:[]};S.tx.push(t);save();closeSheet();render(1);toast(`${a.name} corrected by ${sfmt(diff)}`,()=>{S.tx=S.tx.filter(x=>x.id!==t.id)})},
 def:v=>{S.set.def=v;save();render(1);if(sheets.length){const w=top();w.querySelectorAll('[data-a="def"]').forEach(b=>b.classList.toggle('on',b.dataset.v===v))}toast(`${accOf(v).name} is now the default`)},
 arch:v=>{const a=S.acc.find(x=>x.id===v);if(S.acc.filter(x=>!x.archived).length<2)return toast('Keep at least one account');a.archived=true;if(S.set.def===v)S.set.def=S.acc.find(x=>!x.archived).id;save();closeSheet();render(1);toast(`${a.name} archived`,()=>{a.archived=false})},
 copy:()=>{const t=top().querySelector('#csv');navigator.clipboard.writeText(t.value).then(()=>toast('CSV copied')).catch(()=>{t.select();toast('Select all and copy')})},
 reset:(v,el)=>{if(el.dataset.sure!=='1'){el.dataset.sure='1';el.textContent='Tap again to reset everything';return}fresh();save();applyTheme();while(sheets.length)closeSheet();tab='home';flt='all';q='';roff=0;render();toast(U.demo?'Demo data restored':'All data cleared')},
 logout:()=>{Store.signOut().then(()=>location.replace('login.html'))}
};
document.addEventListener('click',e=>{const el=e.target.closest('[data-a]');if(!el||el.disabled)return;const f=ACT[el.dataset.a];if(f){e.preventDefault();f(el.dataset.v,el,e)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&sheets.length)closeSheet()});

const showMsg=m=>{view.innerHTML=`<div class="empty" style="padding-top:28vh">${m}</div>`};
Store.onStatus(t=>{const el=document.getElementById('syncst');if(el)el.textContent=t;if(/^Couldn/.test(t))toast(t)});
showMsg('Loading your money…');
Store.boot().then(r=>{if(!r){location.replace('login.html');return}U=r.user;S=r.state;if(!S){fresh();save()}if(!S.set.theme)S.set.theme='light';applyTheme();render()}).catch(e=>{console.error(e);showMsg(`Couldn’t load your data. ${esc(e&&e.message||'')}<br><br><button class="btn" onclick="location.reload()">Try again</button>`)});
}
